const JP_MASTERY_THRESHOLD = 3; // respuestas correctas para brillo dorado + 3 estrellas

// ---------------- Progresión por Nivel del Módulo Japonés ----------------
// Pedido explícito (revisado de nuevo en un bloque posterior): Hiragana y
// Katakana COMPLETOS (todas las filas Gojuon + dakuten/handakuten + yōon)
// y la Práctica General deben estar 100% desbloqueados desde el inicio —
// son "lo básico", el usuario tiene que poder practicarlos libremente sin
// candados. La progresión por nivel real queda reservada SOLO para el
// módulo avanzado (Kanji N5, practicado vía Trazos + el Examen de Nivel
// más abajo), que sí se desbloquea de a poco a medida que se sube de
// nivel. jpKanaRowUnlockLevel()/jpYoonRowUnlockLevel() devuelven 1 a
// propósito (no `true`/eliminar el candado del todo): state.level nunca
// baja de 1, así que isJpLevelUnlocked(1) es siempre verdadero, pero se
// mantiene el mismo mecanismo de nivel-requerido que ya usa applyJpLock()/
// getKanaList() en vez de bifurcar la lógica en dos caminos distintos
// (uno con candado, otro sin) — un solo mecanismo, más fácil de auditar.
//
// Vocabulario, Gramática N5 y Práctica de Partículas siguen siendo
// consulta libre sin candado (ver renderN5VocabCategories()/
// renderN5GrammarList()/getParticlePoints() — no llaman a
// isJpLevelUnlocked()), así que sus funciones de "nivel requerido"
// (jpVocabCategoryUnlockLevel/jpGrammarUnlockLevel) se eliminaron por
// completo en vez de dejarlas sin uso.
//
// Nota de alcance honesta: el dataset actual solo cubre kanji N5 (no hay
// N4-N1 todavía, ver #jp-level-toggle "Próximamente" en index.html).
function jpKanaRowUnlockLevel(rowIndex) {
  return 1; // Hiragana/Katakana completos: 100% desbloqueados desde el inicio (pedido explícito)
}
function jpYoonRowUnlockLevel(rowIndex) {
  return 1; // Yōon es parte del mismo alfabeto kana básico, mismo criterio que arriba
}
function jpKanjiUnlockLevel(kanjiIndex) {
  return 30 + Math.floor(kanjiIndex / 2); // único módulo avanzado con progresión real por nivel — ~107 kanji, 2 por nivel → Niveles 30-83
}

// Cuánta XP hace falta ganar (desde el estado actual) para que state.level
// llegue a targetLevel — misma fórmula de crecimiento que grantXP() (+15%
// redondeado por nivel), usada por el Examen de Nivel para otorgar
// exactamente la XP necesaria al demostrar que ya domina contenido
// bloqueado, en vez de mover state.level a mano (eso violaría "los
// usuarios no suben de nivel de forma arbitraria, ganan XP" — pedido
// explícito de un bloque anterior). Sigue siendo XP real, solo que en un
// solo pago grande en vez de goteado en muchas sesiones.
function xpNeededToReachLevel(targetLevel) {
  if (targetLevel <= state.level) return 0;
  let xp = state.xp;
  let xpToNext = state.xpToNext;
  let level = state.level;
  let needed = 0;
  while (level < targetLevel) {
    needed += xpToNext - xp;
    xp = 0;
    xpToNext = Math.round(xpToNext * 1.15);
    level += 1;
  }
  return needed;
}

function isJpLevelUnlocked(requiredLevel) {
  return state.level >= requiredLevel;
}

// notifyJpLocked() vive dentro de la IIFE principal más abajo (necesita
// setAvatarSpeech(), que es local a ese scope) — ver junto a applyJpLock().

// "Fila KA" / "Row KA" en es/en, "KA行" en ja (sufijo, no prefijo — así
// se nombran las filas del Gojuon en japonés real).
function formatGojuonRowLabel(row) {
  if (currentLanguage === "ja") return `${row.romaji}行`;
  return `${t("jpRowLabelPrefix")} ${row.romaji}`;
}

// Lista plana para practicar/quizzear, con forma uniforme sin importar
// el script: `answer` es la romanización para hiragana/katakana, o el
// significado en español para kanji — así showJpQuiz()/handleJpAnswer()
// no necesitan ninguna rama especial por tipo. Filtra contenido todavía
// no desbloqueado por nivel (ver arriba) — así "Práctica General" y la
// práctica por fila nunca preguntan por algo que la cuadrícula muestra
// como candado.
function getKanaList(script) {
  if (script === "kanji") {
    return KANJI_N5.filter((k, i) => isJpLevelUnlocked(jpKanjiUnlockLevel(i))).map((k) => ({
      char: k.char,
      answer: resolveJpMeaning(k.meaning),
      rowId: "kanji-n5",
      script,
      onyomi: k.onyomi,
      kunyomi: k.kunyomi,
      meaning: resolveJpMeaning(k.meaning),
    }));
  }
  const list = [];
  GOJUON_ROWS.forEach((row, rowIndex) => {
    if (!isJpLevelUnlocked(jpKanaRowUnlockLevel(rowIndex))) return;
    row[script].forEach((char, i) => {
      list.push({ char, answer: row.romajiList[i], rowId: row.id, script });
    });
  });
  return list;
}

function shuffleArray(arr) {
  const copy = arr.slice();
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

// Reproduce un carácter/frase japonés con la Web Speech API nativa del
// navegador (sin archivos de audio externos). Sin guardas raras: si el
// navegador no soporta síntesis de voz, simplemente no hace nada.
//
// Chrome/Chromium tiene un bug conocido donde un SpeechSynthesisUtterance
// largo (una oración completa de gramática, por ejemplo) se corta a
// mitad de camino — mismo problema que readerEngine.js ya resuelve para
// las Conversaciones Situacionales (ver partirEnOraciones() ahí). Acá se
// aplica el mismo arreglo: partir por 。！？ y encolar una utterance
// corta por oración en vez de una sola larga.
function speakKanaSentences(texto) {
  const oraciones = texto.split(/(?<=[。！？])/).map((s) => s.trim()).filter(Boolean);
  return oraciones.length ? oraciones : [texto];
}

// Misma selección explícita de voz ja-JP que readerEngine.js (ver
// elegirVozJaponesa() ahí) — reimplementada acá porque este archivo no
// comparte closure con ese módulo. Sin esto, algunos navegadores eligen
// una voz genérica/robótica en vez de una voz nativa japonesa real.
let cachedJaVoiceAppJs = null;
let jaVoiceListenerAttachedAppJs = false;
function elegirVozJaponesaAppJs() {
  if (cachedJaVoiceAppJs || !("speechSynthesis" in window)) return cachedJaVoiceAppJs;
  const voces = window.speechSynthesis.getVoices();
  cachedJaVoiceAppJs = voces.find((v) => v.lang === "ja-JP") || voces.find((v) => v.lang && v.lang.startsWith("ja")) || null;
  if (!cachedJaVoiceAppJs && !jaVoiceListenerAttachedAppJs && voces.length === 0) {
    jaVoiceListenerAttachedAppJs = true;
    window.speechSynthesis.addEventListener("voiceschanged", elegirVozJaponesaAppJs, { once: true });
  }
  return cachedJaVoiceAppJs;
}

async function speakKana(char) {
  if (!("speechSynthesis" in window) || !char) return;
  window.speechSynthesis.cancel(); // corta cualquier lectura anterior en curso
  const oraciones = speakKanaSentences(char);
  for (let i = 0; i < oraciones.length; i++) {
    await new Promise((resolve) => {
      const utterance = new SpeechSynthesisUtterance(oraciones[i]);
      utterance.lang = "ja-JP";
      utterance.rate = 0.8; // pedido explícito: voz pausada y natural (rango 0.75-0.85)
      const voz = elegirVozJaponesaAppJs();
      if (voz) utterance.voice = voz;
      utterance.onend = resolve;
      utterance.onerror = resolve;
      window.speechSynthesis.speak(utterance);
    });
    // Pequeña pausa entre oraciones — mismo criterio que readerEngine.js
    // (pausaEntreOraciones()), evita que el audio suene atropellado.
    if (i < oraciones.length - 1) await new Promise((resolve) => setTimeout(resolve, 220));
  }
}

// Restricción de audio SOLO para los EXÁMENES (evaluación con opciones de
// respuesta, no las vistas de práctica/vocabulario) — pedido explícito:
// en Hiragana/Katakana la pronunciación literalmente ES la respuesta
// correcta (romaji), así que el botón 🔊 queda completamente oculto ahí;
// en Kanji se pregunta el SIGNIFICADO, no la lectura, pero igual solo se
// permite reproducir el audio cuando la interfaz ya está en 日本語 (para
// no dar ninguna pista fuera del modo inmersivo). Los llamados a
// speakKana() en las vistas de práctica (Fases, tarjetas de vocabulario)
// NO pasan por acá — ahí escuchar es parte de estudiar, no de evaluarse.
function isJpExamAudioAllowed(script) {
  if (script === "kanji") return currentLanguage === "ja";
  return false;
}


// Dataset de trazos REALES (Hiragana + Katakana + Kanji), verificado en un
// bloque anterior: @k1low/hanzi-writer-data-jp devuelve {strokes, medians}
// en el mismo formato que Hanzi Writer usa nativamente. Versión fijada
// (no "@latest") para que una publicación futura del paquete no cambie
// el comportamiento sin volver a probarse acá primero. Compartido entre
// el módulo de Práctica de Trazos Reales (#hanzi-writer-modal) y la
// vista de Fases del módulo Japonés — con caché en memoria para no pedir
// dos veces el mismo carácter durante una sesión.
// ---------------------------------------------------
// Módulo de Idiomas: English / Português — misma metodología que
