function rankForLevel(level) {
  let current = RANKS[0].name;
  for (const rank of RANKS) {
    if (level >= rank.level) current = rank.name;
  }
  return current;
}

function formatCurrency(amount, currencyCode) {
  const currency = CURRENCIES[currencyCode] || CURRENCIES.PEN;
  const value = Math.round(amount || 0);
  const formatted = Math.abs(value).toLocaleString(currency.locale);
  const sign = value < 0 ? "-" : "";
  return `${sign}${currency.symbol} ${formatted}`;
}

// Variante con 2 decimales SIN redondear a entero — usada específicamente
// por la pestaña Venta (pedido explícito: "No redondear valores decimales
// a enteros", ejemplos "175.00"/"50.00"). formatCurrency() de arriba
// sigue igual (Math.round) para todo lo demás de la app — Servicio,
// Dashboard, Boleta de Pago, etc. — no era parte de este pedido y
// cambiarla habría alterado esas pantallas sin que nadie lo pidiera.
function formatCurrencyDecimal(amount, currencyCode) {
  const currency = CURRENCIES[currencyCode] || CURRENCIES.PEN;
  const value = amount || 0;
  const formatted = Math.abs(value).toLocaleString(currency.locale, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const sign = value < 0 ? "-" : "";
  return `${sign}${currency.symbol} ${formatted}`;
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return defaultState();
    const parsed = JSON.parse(raw);
    const base = defaultState();

    const mergedFisico = {
      ...base.pillars.fisico,
      ...(parsed.pillars && parsed.pillars.fisico),
      steps: {
        ...base.pillars.fisico.steps,
        ...(parsed.pillars && parsed.pillars.fisico && parsed.pillars.fisico.steps),
      },
    };

    const parsedFinanzas = parsed.pillars && parsed.pillars.finanzas;
    const mergedFinanzas = {
      ...base.pillars.finanzas,
      ...parsedFinanzas,
      categories:
        parsedFinanzas && Array.isArray(parsedFinanzas.categories) && parsedFinanzas.categories.length
          ? parsedFinanzas.categories
          : base.pillars.finanzas.categories,
    };

    const parsedAprendizaje = parsed.pillars && parsed.pillars.aprendizaje;
    const mergedAprendizaje = {
      ...base.pillars.aprendizaje,
      ...parsedAprendizaje,
      mastery: { ...base.pillars.aprendizaje.mastery, ...(parsedAprendizaje && parsedAprendizaje.mastery) },
    };

    return {
      ...base,
      ...parsed,
      // Migración: perfiles guardados antes de que existiera el Héroe
      // unificado ya tienen `playerCharacter` (Fesha/Mijashi) pero nunca
      // `avatar` — se adopta ese valor como avatar de entrada para que no
      // se les pida elegir de nuevo (openCharacterSelectModal() solo se
      // dispara si `avatar` sigue siendo null de verdad).
      avatar: parsed.avatar || parsed.playerCharacter || base.avatar,
      pillars: {
        finanzas: mergedFinanzas,
        fisico: mergedFisico,
        espiritual: { ...base.pillars.espiritual, ...(parsed.pillars && parsed.pillars.espiritual) },
        aprendizaje: mergedAprendizaje,
      },
      wishlist: Array.isArray(parsed.wishlist) && parsed.wishlist.length ? parsed.wishlist : base.wishlist,
      chatHistory: Array.isArray(parsed.chatHistory) ? parsed.chatHistory : base.chatHistory,
    };
  } catch (err) {
    return defaultState();
  }
}

let state = loadState();

function persist() {
  // Defensa contra progreso "fantasma": el Nivel nunca baja en este
  // juego (no existe ningún flujo que reste state.level), así que si lo
  // que ya está guardado en localStorage tiene un Nivel MÁS ALTO que el
  // que esta pestaña tiene en memoria, es porque otra pestaña/ventana
  // (o la PWA instalada, abierta aparte del navegador) con el mismo
  // perfil ya guardó progreso más nuevo mientras esta quedó con una
  // copia vieja en memoria — sin este chequeo, el próximo persist() de
  // ESTA pestaña (por cualquier acción menor: cambiar de idioma, abrir
  // un modal, etc.) pisaría ese progreso más nuevo con uno más viejo,
  // dando la sensación de que "el Nivel volvió a 1" al recargar. Se
  // adopta ese progreso más alto a memoria antes de guardar, en vez de
  // perderlo.
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (stored && typeof stored.level === "number" && stored.level > state.level) {
      console.warn(
        `Miikaeru: se encontró Nivel ${stored.level} ya guardado (esta pestaña tenía Nivel ${state.level} en memoria) — se adopta el más alto para no perder progreso.`
      );
      state.level = stored.level;
      state.xp = stored.xp;
      state.xpToNext = stored.xpToNext;
      state.gold = stored.gold;
      state.diamonds = stored.diamonds;
    }
  } catch (err) {
    // localStorage corrupto/vacío: no hay nada que adoptar, se sigue de largo.
  }

  // El campo `image` de los mensajes de chat vive solo en memoria de sesión,
  // por eso se excluye al serializar hacia localStorage.
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state, (key, value) => (key === "image" ? undefined : value)));
}

